from html.parser import HTMLParser
from pathlib import Path
from urllib.parse import urljoin, urlsplit
import hashlib, json, re

source = Path('products/services/wordpress-migration-qa-pilot/raw/jobs-index.html')
base = 'https://jobs.wordpress.net/'
raw = source.read_bytes()

class JobLinks(HTMLParser):
    def __init__(self):
        super().__init__()
        self.current = None
        self.links = {}

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            href = dict(attrs).get('href') or ''
            url = urljoin(base, href)
            parts = urlsplit(url)
            self.current = (url, []) if parts.netloc == 'jobs.wordpress.net' and re.fullmatch(r'/job/[^/]+/?', parts.path) else None

    def handle_data(self, data):
        if self.current:
            self.current[1].append(data)

    def handle_endtag(self, tag):
        if tag == 'a' and self.current:
            url, chunks = self.current
            label = ' '.join(' '.join(chunks).split())
            if label:
                self.links.setdefault(url, set()).add(label)
            self.current = None

parser = JobLinks()
parser.feed(raw.decode('utf-8', errors='replace'))
keywords = re.compile(r'\bmigrat\w*|\bquality assurance\b|\bqa\b|\bredirects?\b|\bcontent audit\b', re.I)
leads = [{'url': url, 'matched_anchor_text': sorted(label for label in labels if keywords.search(label))} for url, labels in sorted(parser.links.items()) if any(keywords.search(label) for label in labels)]
report = {'source_url': base, 'source_file': str(source), 'sha256': hashlib.sha256(raw).hexdigest(), 'distinct_job_urls_with_visible_anchor_text': len(parser.links), 'leads': leads, 'coverage': 'One saved static index. Matches are navigation leads. The original brief controls scope and eligibility. Zero extracted links would indicate no usable extraction coverage.'}
output = source.parent.parent / 'director-index-anchor-evidence.json'
output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(output.read_text(encoding='utf-8'))
